<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\Holder;

use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesVO;
use Civi\Lughauth\Features\Access\UserRoleAssignment\Domain\ValueObject\UserRoleAssignmentRolesListRef;

trait UserRoleAssignmentRolesAttributeHolder
{
    protected UserRoleAssignmentRolesVO|UserRoleAssignmentRolesListRef| array |null $roles = null;
    protected bool $rolesAssigned = false;

    public function getRolesOrCurrent(UserRoleAssignmentRolesVO $roles): UserRoleAssignmentRolesVO
    {
        if ($this->rolesAssigned) {
            $current = UserRoleAssignmentRolesVO::from($this->roles);
            return $current->getWithDefaults($roles) ?? $current;
        } else {
            return $roles;
        }
    }
    public function rolesTryBuildInitial(ConstraintFailList $error): ?UserRoleAssignmentRolesVO
    {
        return  UserRoleAssignmentRolesVO::tryFrom($this->rolesAssigned ? $this->roles : null, $error);
    }
    public function roles(UserRoleAssignmentRolesVO|UserRoleAssignmentRolesListRef| array |null $roles): static
    {
        $this->roles = $roles;
        $this->rolesAssigned = true;
        return $this;
    }
    public function getRoles(): ?UserRoleAssignmentRolesListRef
    {
        return $this->roles instanceof UserRoleAssignmentRolesVO ? $this->roles->value() : $this->roles;
    }
    public function isRolesAssigned(): bool
    {
        return $this->rolesAssigned;
    }
    public function writeRolesTo(mixed $att): void
    {
        if ($this->rolesAssigned) {
            \assert(null !== $this->roles);
            $att->roles($this->roles);
        }
    }
    public function readRolesFrom(mixed $att): void
    {
        if ($att->isRolesAssigned()) {
            $roles = $att->getRoles();
            \assert(null !== $roles);
            $this->roles($roles);
        }
    }
    public function unsetRoles(): static
    {
        $this->rolesAssigned = false;
        return $this;
    }
    protected function withDefaultRoles(): void
    {
    }
    protected function withAssertedRolesRules(self $value, ConstraintFailList $errorsList): void
    {
        if ($value->rolesAssigned = $this->rolesAssigned) {
            $value->roles = UserRoleAssignmentRolesVO::tryFrom($this->roles, $errorsList);
        }
    }
}
